import math

def check_n3(x1, x2):
    """Checks if an integer x3 exists for given x1, x2."""
    # (x3 + 1)(x1 + 1) = x2^2 + 1
    A = x1 + 1
    RHS = x2**2 + 1

    if RHS % A == 0:
        B = RHS // A
        x3 = B - 1
        if x3 >= 1:
            return x3
    return None

def check_n4(x1, x2):
    """Checks if an integer x4 exists for given x1, x2."""
    # Step 1: Find x3
    x3 = check_n3(x1, x2)
    if x3 is None:
        return None

    # Step 2: Find x4
    # (x4 + 1)(x2 + 1) = x3^2 + 1
    A_prime = x2 + 1
    RHS_prime = x3**2 + 1

    if RHS_prime % A_prime == 0:
        B_prime = RHS_prime // A_prime
        x4 = B_prime - 1
        if x4 >= 1:
            return x4
    return None

# Systematic test for small values (x1, x2 from 1 to 5)
MAX_VAL = 5
results_n3 = {}
results_n4 = {}

print("--- Testing N=3 ---")
for x1 in range(1, MAX_VAL + 1):
    for x2 in range(1, MAX_VAL + 1):
        x3 = check_n3(x1, x2)
        if x3 is not None:
            results_n3[(x1, x2)] = x3
            print(f"Found solution for N=3: (x1={x1}, x2={x2}) -> x3={x3}")

print("\n--- Testing N=4 ---")
for x1 in range(1, MAX_VAL + 1):
    for x2 in range(1, MAX_VAL + 1):
        x4 = check_n4(x1, x2)
        if x4 is not None:
            results_n4[(x1, x2)] = x4
            print(f"Found solution for N=4: (x1={x1}, x2={x2}) -> x3=?, x4={x4}")

